CREATE TABLE tk_account (owner_id VARCHAR(400) PRIMARY KEY REFERENCES tk_owner(id), username VARCHAR(64) UNIQUE, password_hash VARCHAR(400), display_name VARCHAR(400) NOT NULL, state VARCHAR(16) NOT NULL CHECK((state='UNCLAIMED' OR state='ENABLED' OR state='DISABLED')), administrator BOOLEAN NOT NULL, initialized BOOLEAN DEFAULT FALSE NOT NULL, version BIGINT NOT NULL CHECK(version>=0), CHECK ((username IS NULL AND password_hash IS NULL AND state='UNCLAIMED') OR (username IS NOT NULL AND password_hash IS NOT NULL AND (state='ENABLED' OR state='DISABLED'))));
CREATE TABLE tk_auth_control (id INTEGER PRIMARY KEY CHECK(id=1), bootstrap_completed BOOLEAN NOT NULL);
INSERT INTO tk_auth_control VALUES(1,FALSE);
CREATE TABLE tk_auth_challenge (digest VARCHAR(64) PRIMARY KEY, purpose VARCHAR(16) NOT NULL CHECK((purpose='SETUP' OR purpose='RECOVERY')), owner_id VARCHAR(400) REFERENCES tk_owner(id), expires_at VARCHAR(40) NOT NULL, consumed BOOLEAN NOT NULL);
CREATE TABLE tk_auth_session (digest VARCHAR(64) PRIMARY KEY, owner_id VARCHAR(400) NOT NULL REFERENCES tk_account(owner_id), csrf VARCHAR(64) NOT NULL, permissions VARCHAR(16) NOT NULL CHECK((permissions='READ' OR permissions='READ_WRITE')), created_at VARCHAR(40) NOT NULL, expires_at VARCHAR(40) NOT NULL, last_seen_at VARCHAR(40) NOT NULL, persistent BOOLEAN NOT NULL, parent_digest VARCHAR(64));
CREATE INDEX tk_auth_session_owner ON tk_auth_session(owner_id);
CREATE TABLE tk_api_token (digest VARCHAR(64) PRIMARY KEY, id UUID NOT NULL UNIQUE, owner_id VARCHAR(400) NOT NULL REFERENCES tk_account(owner_id), name VARCHAR(400) NOT NULL, permissions VARCHAR(16) NOT NULL CHECK((permissions='READ' OR permissions='READ_WRITE')), expires_at VARCHAR(40), revoked BOOLEAN NOT NULL, source VARCHAR(16) NOT NULL CHECK((source='LEGACY' OR source='MANAGED')), created_at VARCHAR(40) NOT NULL, last_used_at VARCHAR(40), version BIGINT NOT NULL CHECK(version>=0), legacy_digest VARCHAR(64), UNIQUE(owner_id,digest));
ALTER TABLE tk_auth_session ADD CONSTRAINT tk_auth_session_parent FOREIGN KEY(owner_id,parent_digest) REFERENCES tk_api_token(owner_id,digest);
CREATE INDEX tk_api_token_owner ON tk_api_token(owner_id);
CREATE TABLE tk_auth_throttle (id VARCHAR(64) PRIMARY KEY, attempts INTEGER NOT NULL CHECK(attempts>=0), window_start VARCHAR(40) NOT NULL);
